// Evolution API manda su propio formato. Acá se normaliza a lo que espera el resto
// del flujo: body.businessId / body.phone / body.message / body.sender.
// El businessId viaja en la query del webhook, así cada negocio tiene su propia URL.
const raw = $('Webhook').item.json;
const query = raw.query || {};
const body = raw.body || {};
const data = body.data || {};

// Formato Evolution
const remoteJid = data?.key?.remoteJid || '';
const phoneFromJid = remoteJid.split('@')[0] || '';
const evolutionText =
  data?.message?.conversation ||
  data?.message?.extendedTextMessage?.text ||
  data?.message?.imageMessage?.caption ||
  '';

// Si alguien llama al webhook ya normalizado (pruebas), se respeta tal cual.
const businessId = body.businessId || query.businessId || '';
const phone = body.phone || (phoneFromJid ? '+' + phoneFromJid : '');
const message = body.message || evolutionText;
const sender = body.sender || data?.pushName || body.pushName || '';

// Qué NO se atiende nunca:
// - Grupos y listas de difusión: su JID es '...@g.us' / '...@broadcast' y trae 18 dígitos,
//   no un teléfono. Antes el agente contestaba dentro de grupos ajenos al negocio y hasta
//   creaba "clientes" con el id del grupo.
// - Los estados de WhatsApp y los mensajes que manda el propio número del negocio.
// - Mensajes vacíos o sin negocio.
const fromMe = Boolean(data?.key?.fromMe);
const isGroup = /@g\.us$/i.test(remoteJid) || /@broadcast$/i.test(remoteJid) || /^status@/i.test(remoteJid);
const digits = String(phone).replace(/\D/g, '');
const atender = Boolean(businessId) && !isGroup && !fromMe
  && digits.length >= 8 && digits.length <= 15
  && String(message).trim().length > 0;

return [{
  json: {
    body: { businessId, phone, message, sender },
    headers: raw.headers || {},
    fromMe,
    isGroup,
    atender,
    messageKey: data?.key || null,
    instance: body.instance || raw.body?.instance || 'Agen',
  },
}];

